import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Look for features with strong associations to outcome
    scores = []
    for fid in feats.ids:
        col = feats.column(fid)
        t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, col], feats.x[feats.y==0, col])
        scores.append((abs(t_stat), fid))

    scores.sort(reverse=True)

    # Get top features, but limit to MAX_DRIVERS
    drivers = [fid for _, fid in scores[:MAX_DRIVERS]]

    # Remove near-duplicates based on correlation
    keep_features = set()
    used = set()

    # Simple approach: just take first few non-correlated ones
    for fid in drivers:
        if fid in used:
            continue
        keep_features.add(fid)
        used.add(fid)
        # Mark correlated features as used
        for other_fid in feats.ids:
            if other_fid != fid:
                corr = np.corrcoef(feats.x[:, feats.column(fid)], feats.x[:, feats.column(other_fid)])[0,1]
                if abs(corr) >= 0.6:
                    used.add(other_fid)
        if len(keep_features) >= MAX_DRIVERS:
            break

    # If no strong drivers found, return empty design
    if not keep_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Return design with selected drivers
    return Design(
        drivers=tuple(keep_features),
        columns=tuple(keep_features),
        products=(),
        loadings={}
    )

